-- ADR-0235: payroll with KPI evaluation (module payroll). New tables only (ADR-0206). Generated by
-- drizzle-kit; added by hand: the REVOKEs (the rates, templates, terms, advances and runs are never
-- deleted) and the trigger that keeps the lines, KPI items and adjustment lines of an APPROVED run
-- from any insert, update or delete. A draft run's lines are working paper and may be rebuilt.
CREATE TABLE "payroll_advances" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "payroll_advances_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"user_id" bigint NOT NULL,
	"month" text NOT NULL,
	"amount" numeric(14, 2) NOT NULL,
	"paid_on" date NOT NULL,
	"note" text,
	"created_by" bigint NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"voided_at" timestamp with time zone,
	"voided_by" bigint,
	"void_reason" text,
	CONSTRAINT "payroll_advances_month" CHECK ("payroll_advances"."month" ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
	CONSTRAINT "payroll_advances_amount" CHECK ("payroll_advances"."amount" > 0),
	CONSTRAINT "payroll_advances_note" CHECK ("payroll_advances"."note" IS NULL OR length("payroll_advances"."note") BETWEEN 1 AND 300),
	CONSTRAINT "payroll_advances_voided" CHECK (("payroll_advances"."voided_at" IS NULL) = ("payroll_advances"."voided_by" IS NULL) AND ("payroll_advances"."voided_at" IS NULL) = ("payroll_advances"."void_reason" IS NULL))
);
--> statement-breakpoint
CREATE TABLE "payroll_kpi_templates" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "payroll_kpi_templates_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"name" text NOT NULL,
	"items" jsonb NOT NULL,
	"archived_at" timestamp with time zone,
	"created_by" bigint NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "payroll_kpi_templates_name_present" CHECK (length(btrim("payroll_kpi_templates"."name")) BETWEEN 1 AND 80),
	CONSTRAINT "payroll_kpi_templates_items_array" CHECK (jsonb_typeof("payroll_kpi_templates"."items") = 'array')
);
--> statement-breakpoint
