	CONSTRAINT "payroll_line_adjustments_amount" CHECK ("payroll_line_adjustments"."amount" > 0),
	CONSTRAINT "payroll_line_adjustments_name" CHECK (length(btrim("payroll_line_adjustments"."name")) BETWEEN 1 AND 80),
	CONSTRAINT "payroll_line_adjustments_taxable" CHECK ("payroll_line_adjustments"."kind" = 'ADDITION' OR NOT "payroll_line_adjustments"."taxable")
);
