CREATE FUNCTION "payroll_line_keep_approved"() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  run bigint;
BEGIN
  IF TG_OP = 'INSERT' THEN run := NEW."run_id"; ELSE run := OLD."run_id"; END IF;
  IF EXISTS (SELECT 1 FROM "payroll_runs" WHERE "id" = run AND "status" = 'APPROVED') THEN
    RAISE EXCEPTION 'payroll run % is approved: its lines do not change', run USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW."run_id" <> OLD."run_id" THEN
    RAISE EXCEPTION 'a payroll line never moves to another run' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE FUNCTION "payroll_line_part_keep_approved"() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  line bigint;
BEGIN
  IF TG_OP = 'INSERT' THEN line := NEW."line_id"; ELSE line := OLD."line_id"; END IF;
  IF EXISTS (
    SELECT 1 FROM "payroll_lines" l JOIN "payroll_runs" r ON r."id" = l."run_id"
     WHERE l."id" = line AND r."status" = 'APPROVED'
  ) THEN
    RAISE EXCEPTION 'payroll line % is on an approved run: it does not change', line USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW."line_id" <> OLD."line_id" THEN
    RAISE EXCEPTION 'a payslip row never moves to another line' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER "payroll_lines_keep_approved" BEFORE INSERT OR UPDATE OR DELETE ON "payroll_lines"
  FOR EACH ROW EXECUTE FUNCTION "payroll_line_keep_approved"();--> statement-breakpoint
CREATE TRIGGER "payroll_line_items_keep_approved" BEFORE INSERT OR UPDATE OR DELETE ON "payroll_line_items"
  FOR EACH ROW EXECUTE FUNCTION "payroll_line_part_keep_approved"();--> statement-breakpoint
CREATE TRIGGER "payroll_line_adjustments_keep_approved" BEFORE INSERT OR UPDATE OR DELETE ON "payroll_line_adjustments"
  FOR EACH ROW EXECUTE FUNCTION "payroll_line_part_keep_approved"();
